candidates.raw:
size_t i;
size_t worst_index = 0;
double worst = -1.0;
size_t full_count;
adcs_quat_t full_q;
adcs_status_t st;

/* 默认输出 */
qr_output.mode = QR_MONITOR;
qr_output.good = qr_state.good;
qr_output.worst_residual_rad = 0.0;
qr_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
qr_output.used_count = 0U;
qr_output.rejected_outlier = 0;

/* 使能关闭 */
if (qr_input.enable == 0) {
    qr_state.mode = QR_OFF;
    qr_state.good = 0U;
    qr_output.mode = QR_OFF;
    qr_output.good = 0U;
    return;
}

/* 配置合法性 */
if ((!isfinite(qr_config.residual_limit_rad)) ||
    (qr_config.residual_limit_rad < 0.0) ||
    (qr_config.residual_limit_rad > ADCS_PI) ||
    (qr_config.required_good < 1U) || (qr_config.required_good > 20U) ||
    ((qr_config.allow_outlier_reject != 0) && (qr_config.allow_outlier_reject != 1))) {
    qr_state.mode = QR_FAULT;
    qr_state.good = 0U;
    qr_output.mode = QR_FAULT;
    qr_output.good = 0U;
    return;
}

/* 输入合法性 */
if ((qr_input.body == NULL) || (qr_input.inertial == NULL) || (qr_input.weights == NULL) ||
    (qr_input.count < 2U) || (qr_input.count > 4U)) {
    qr_state.mode = QR_FAULT;
    qr_state.good = 0U;
    qr_output.mode = QR_FAULT;
    qr_output.good = 0U;
    return;
}
for (i = 0; i < qr_input.count; i++) {
    if ((!adcs_is_finite_vec3(&qr_input.body[i])) ||
        (!adcs_is_finite_vec3(&qr_input.inertial[i])) ||
        (!isfinite(qr_input.weights[i])) || (qr_input.weights[i] <= 0.0)) {
        qr_state.mode = QR_FAULT;
        qr_state.good = 0U;
        qr_output.mode = QR_FAULT;
        qr_output.good = 0U;
        return;
    }
}

/* 全量 QUEST */
st = adcs_quest(qr_input.body, qr_input.inertial, qr_input.weights, qr_input.count, &full_q);
if (st != ADCS_OK) {
    qr_state.mode = QR_FAULT;
    qr_state.good = 0U;
    qr_output.mode = QR_FAULT;
    qr_output.good = 0U;
    return;
}

/* 全量最坏残差 */
{
    adcs_mat3_t dcm = adcs_quat_to_dcm_bi(&full_q);
    for (i = 0; i < qr_input.count; i++) {
        adcs_vec3_t bn, bi, bn_rot;
        double r;
        if (adcs_vec3_normalize(&qr_input.body[i], ADCS_EPS_NORM, &bn) != ADCS_OK ||
            adcs_vec3_normalize(&qr_input.inertial[i], ADCS_EPS_NORM, &bi) != ADCS_OK) {
            qr_state.mode = QR_FAULT;
            qr_state.good = 0U;
            qr_output.mode = QR_FAULT;
            qr_output.good = 0U;
            return;
        }
        bn_rot = adcs_mat3_mul_vec(&dcm, &bi);
        bn_rot = adcs_vec3_sub(&bn_rot, &bn);
        r = adcs_vec3_norm(&bn_rot);
        if (r > worst) {
            worst = r;
            worst_index = i;
        }
    }
}

full_count = qr_input.count;
qr_output.q_bi = full_q;
qr_output.used_count = (unint32)full_count;
qr_output.rejected_outlier = 0;
qr_output.worst_residual_rad = worst;

/* 单点剔除重试 */
if ((worst > qr_config.residual_limit_rad) && (qr_config.allow_outlier_reject != 0) &&
    (full_count > 2U)) {
    adcs_vec3_t body_red[4];
    adcs_vec3_t iner_red[4];
    double w_red[4];
    size_t k = 0;
    adcs_quat_t red_q;
    size_t red_worst_index = 0;
    double red_worst = -1.0;

    for (i = 0; i < full_count; i++) {
        if (i == worst_index) continue;
        body_red[k] = qr_input.body[i];
        iner_red[k] = qr_input.inertial[i];
        w_red[k] = qr_input.weights[i];
        k++;
    }
    st = adcs_quest(body_red, iner_red, w_red, k, &red_q);
    if (st == ADCS_OK) {
        adcs_mat3_t dcm = adcs_quat_to_dcm_bi(&red_q);
        for (i = 0; i < k; i++) {
            adcs_vec3_t bn, bi, bn_rot;
            double r;
            (void)adcs_vec3_normalize(&body_red[i], ADCS_EPS_NORM, &bn);
            (void)adcs_vec3_normalize(&iner_red[i], ADCS_EPS_NORM, &bi);
            bn_rot = adcs_mat3_mul_vec(&dcm, &bi);
            bn_rot = adcs_vec3_sub(&bn_rot, &bn);
            r = adcs_vec3_norm(&bn_rot);
            if (r > red_worst) {
                red_worst = r;
                red_worst_index = i;
            }
        }
        (void)red_worst_index;
        if (red_worst <= qr_config.residual_limit_rad) {
            qr_output.q_bi = red_q;
            qr_output.used_count = (unint32)k;
            qr_output.rejected_outlier = 1;
            qr_output.worst_residual_rad = red_worst;
        }
    }
}

/* 一致性决策 */
if (qr_state.mode == QR_FAULT) {
    qr_state.good = qr_state.good;
    qr_output.mode = QR_FAULT;
    qr_output.good = qr_state.good;
    return;
}

if (qr_output.worst_residual_rad <= qr_config.residual_limit_rad) {
    qr_state.good++;
    if (qr_state.good >= qr_config.required_good) {
        qr_state.mode = QR_READY;
    } else {
        qr_state.mode = QR_MONITOR;
    }
} else {
    qr_state.mode = QR_MONITOR;
    qr_state.good = 0U;
}

qr_output.mode = qr_state.mode;
qr_output.good = qr_state.good;

