double res;
adcs_vec3_t body_n, inertial_n;
adcs_vec3_t rotated;
adcs_mat3_t dcm;
adcs_status_t st;
adcs_quat_t q_full;
adcs_quat_t q_reduced;
double reduced_worst;
int fault_latched = 0;
int accepted_reduced = 0;

if(qr_input.enable == 0){
    qr_state.mode = QR_OFF;
    qr_state.good = 0U;
    qr_output.mode = QR_OFF;
    qr_output.good = 0U;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1,0,0,0};
    qr_output.used_count = 0U;
    qr_output.rejected_outlier = 0;
    return;
}

if((!isfinite(qr_config.residual_limit_rad)) ||
   (qr_config.residual_limit_rad < 0.0) ||
   (qr_config.residual_limit_rad > ADCS_PI) ||
   (qr_config.required_good < 1U) || (qr_config.required_good > 20U) ||
   ((qr_config.allow_outlier_reject != 0) && (qr_config.allow_outlier_reject != 1)) ||
   (qr_input.body == NULL) || (qr_input.inertial == NULL) || (qr_input.weights == NULL) ||
   (qr_input.count < 2U) || (qr_input.count > 4U)){
    qr_state.mode = QR_FAULT;
