    qr_output.mode = QR_FAULT;
    qr_output.good = 0U;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1,0,0,0};
    qr_output.used_count = qr_input.count;
    qr_output.rejected_outlier = 0;
    return;
}

for(i = 0U; i < qr_input.count; i++){
    if((!adcs_is_finite_vec3(&qr_input.body[i])) ||
       (!adcs_is_finite_vec3(&qr_input.inertial[i])) ||
       (!isfinite(qr_input.weights[i])) || (qr_input.weights[i] <= 0.0)){
        qr_state.mode = QR_FAULT;
        qr_state.good = 0U;
        qr_output.mode = QR_FAULT;
        qr_output.good = 0U;
        qr_output.worst_residual_rad = 0.0;
        qr_output.q_bi = (adcs_quat_t){1,0,0,0};
        qr_output.used_count = qr_input.count;
        qr_output.rejected_outlier = 0;
        return;
    }
}

st = adcs_quest(qr_input.body, qr_input.inertial, qr_input.weights, qr_input.count, &q_full);
if(st != ADCS_OK){
    qr_state.mode = QR_FAULT;
    qr_state.good = 0U;
    qr_output.mode = QR_FAULT;
    qr_output.good = 0U;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1,0,0,0};
    qr_output.used_count = qr_input.count;
    qr_output.rejected_outlier = 0;
    return;
}

dcm = adcs_quat_to_dcm_bi(&q_full);
worst_res = -1.0;
worst_idx = 0U;
for(i = 0U; i < qr_input.count; i++){
    if(adcs_vec3_normalize(&qr_input.body[i], ADCS_EPS_NORM, &body_n) != ADCS_OK){
        qr_state.mode = QR_FAULT;
        qr_state.good = 0U;
        qr_output.mode = QR_FAULT;
        qr_output.good = 0U;
        qr_output.worst_residual_rad = 0.0;
        qr_output.q_bi = (adcs_quat_t){1,0,0,0};
        qr_output.used_count = qr_input.count;
        qr_output.rejected_outlier = 0;
        return;
    }
    if(adcs_vec3_normalize(&qr_input.inertial[i], ADCS_EPS_NORM, &inertial_n) != ADCS_OK){
        qr_state.mode = QR_FAULT;
        qr_state.good = 0U;
        qr_output.mode = QR_FAULT;
        qr_output.good = 0U;
        qr_output.worst_residual_rad = 0.0;
        qr_output.q_bi = (adcs_quat_t){1,0,0,0};
        qr_output.used_count = qr_input.count;
        qr_output.rejected_outlier = 0;
        return;
    }
    rotated = adcs_mat3_mul_vec(&dcm, &inertial_n);
    res = acos(ADCS_CLAMP(adcs_vec3_dot(&body_n, &rotated), -1.0, 1.0));
    if(res > worst_res){
        worst_res = res;
        worst_idx = i;
