size_t i, worst_idx = 0;
int valid = 1;
adcs_quat_t q_full, q_red;
adcs_mat3_t c_bi;
double full_worst = -1.0, red_worst = -1.0;
size_t used_count_out = 0;

/* 参数与输入校验 */
if ((!isfinite(qr_config.residual_limit_rad)) ||
    (qr_config.residual_limit_rad < 0.0) ||
    (qr_config.residual_limit_rad > ADCS_PI)) {
    valid = 0;
}
if ((qr_config.required_good < 1U) || (qr_config.required_good > 20U)) {
    valid = 0;
}
if ((qr_config.allow_outlier_reject != 0) && (qr_config.allow_outlier_reject != 1)) {
    valid = 0;
}
if ((qr_input.enable != 0) && (qr_input.enable != 1)) {
    valid = 0;
}
if ((qr_input.body == NULL) || (qr_input.inertial == NULL) ||
    (qr_input.weights == NULL) || (qr_input.count < 2U) || (qr_input.count > 4U)) {
    valid = 0;
}
if (valid) {
    for (i = 0; i < qr_input.count; i++) {
        if ((!adcs_is_finite_vec3(&qr_input.body[i])) ||
            (!adcs_is_finite_vec3(&qr_input.inertial[i])) ||
            (!isfinite(qr_input.weights[i])) || (qr_input.weights[i] <= 0.0)) {
            valid = 0;
            break;
        }
    }
}

if (!valid) {
    qr_state.mode = QR_FAULT;
    qr_state.good = 0U;
    qr_output.mode = QR_FAULT;
    qr_output.good = 0U;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    qr_output.used_count = 0U;
    qr_output.rejected_outlier = 0;
    return;
}

/* enable == 0：OFF，复位 */
if (qr_input.enable == 0) {
    qr_state.mode = QR_OFF;
    qr_state.good = 0U;
    qr_output.mode = QR_OFF;
    qr_output.good = 0U;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    qr_output.used_count = 0U;
    qr_output.rejected_outlier = 0;
    return;
}

/* 全集 QUEST 求解 */
if (adcs_quest(qr_input.body, qr_input.inertial, qr_input.weights,
               qr_input.count, &q_full) != ADCS_OK) {
    qr_state.mode = QR_FAULT;
    qr_state.good = 0U;
    qr_output.mode = QR_FAULT;
    qr_output.good = 0U;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    qr_output.used_count = 0U;
    qr_output.rejected_outlier = 0;
    return;
}

/* 全集最差残差：逐个观测扫描，挑出唯一最差下标 */
c_bi = adcs_quat_to_dcm_bi(&q_full);
full_worst = -1.0;
worst_idx = 0;
for (i = 0; i < qr_input.count; i++) {
    adcs_vec3_t rot, ib, bb;
    double dot, ang;
    rot = adcs_mat3_mul_vec(&c_bi, &qr_input.inertial[i]);
    adcs_vec3_normalize(&rot, ADCS_EPS_NORM, &rot);
    adcs_vec3_normalize(&qr_input.inertial[i], ADCS_EPS_NORM, &ib);
    adcs_vec3_normalize(&qr_input.body[i], ADCS_EPS_NORM, &bb);
    (void)ib;
    dot = adcs_vec3_dot(&rot, &bb);
    if (dot > 1.0) dot = 1.0;
    if (dot < -1.0) dot = -1.0;
    ang = acos(dot);
    if (ang > full_worst) {
        full_worst = ang;
        worst_idx = i;
    }
}

used_count_out = qr_input.count;
qr_output.q_bi = q_full;
qr_output.worst_residual_rad = full_worst;
qr_output.rejected_outlier = 0;

/* 单离群剔除重试：仅当三条件同时成立，且只剔除唯一最差 */
if ((full_worst > qr_config.residual_limit_rad) &&
    (qr_config.allow_outlier_reject != 0) && (qr_input.count > 2U)) {
    adcs_vec3_t body_red[4];
    adcs_vec3_t iner_red[4];
    double w_red[4];
    size_t j = 0;
    for (i = 0; i < qr_input.count; i++) {
        if (i == worst_idx) continue;
        body_red[j] = qr_input.body[i];
        iner_red[j] = qr_input.inertial[i];
        w_red[j] = qr_input.weights[i];
        j++;
    }
    if (adcs_quest(body_red, iner_red, w_red, j, &q_red) == ADCS_OK) {
        size_t k;
        adcs_mat3_t c_red = adcs_quat_to_dcm_bi(&q_red);
        red_worst = -1.0;
        for (k = 0; k < j; k++) {
            adcs_vec3_t rot2, bb2;
            double dot2, ang2;
            rot2 = adcs_mat3_mul_vec(&c_red, &iner_red[k]);
            adcs_vec3_normalize(&rot2, ADCS_EPS_NORM, &rot2);
            adcs_vec3_normalize(&body_red[k], ADCS_EPS_NORM, &bb2);
            dot2 = adcs_vec3_dot(&rot2, &bb2);
            if (dot2 > 1.0) dot2 = 1.0;
            if (dot2 < -1.0) dot2 = -1.0;
            ang2 = acos(dot2);
            if (ang2 > red_worst) red_worst = ang2;
        }
        if (red_worst <= qr_config.residual_limit_rad) {
            qr_output.q_bi = q_red;
            qr_output.worst_residual_rad = red_worst;
            used_count_out = j;
            qr_output.rejected_outlier = 1;
        }
    }
}

qr_output.used_count = (unint32)used_count_out;

/* 一致性判定：使用接受后的最差残差 */
if (qr_output.worst_residual_rad <= qr_config.residual_limit_rad) {
    qr_state.good = qr_state.good + 1U;
    if (qr_state.good >= qr_config.required_good) {
        qr_state.mode = QR_READY;
    } else {
        qr_state.mode = QR_MONITOR;
    }
} else {
    qr_state.good = 0U;
    qr_state.mode = QR_MONITOR;
}
qr_output.mode = qr_state.mode;
qr_output.good = qr_state.good;

